import{_ as n,o as a,c as s,a6 as t}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"连接管理","description":"Connection、Keep-Alive、Upgrade、Expect——持久连接与逐跳字段的处理规则。","frontmatter":{"title":"连接管理","description":"Connection、Keep-Alive、Upgrade、Expect——持久连接与逐跳字段的处理规则。","source":"https://daiw.org/manual/http11/connection-management"},"headers":[],"relativePath":"manual/computer-programming/http11/connection-management.md","filePath":"manual/computer-programming/http11/connection-management.md"}'),o={name:"manual/computer-programming/http11/connection-management.md"};function i(p,e,l,r,c,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="连接管理" tabindex="-1">连接管理 <a class="header-anchor" href="#连接管理" aria-label="Permalink to &quot;连接管理&quot;">​</a></h1><h2 id="持久连接的默认行为" tabindex="-1">持久连接的默认行为 <a class="header-anchor" href="#持久连接的默认行为" aria-label="Permalink to &quot;持久连接的默认行为&quot;">​</a></h2><p>HTTP/1.1 中<strong>持久连接是默认</strong>，无需任何字段声明。与 HTTP/1.0 相反：</p><table tabindex="0"><thead><tr><th>版本</th><th>默认</th><th>关闭方式</th><th>保持方式</th></tr></thead><tbody><tr><td>HTTP/1.0</td><td>短连接</td><td>默认即关</td><td><code>Connection: keep-alive</code></td></tr><tr><td>HTTP/1.1</td><td><strong>持久</strong></td><td><code>Connection: close</code></td><td>默认</td></tr></tbody></table><p>任一方都可在<strong>任意时刻</strong>关闭连接，接收方必须能处理。发送 <code>Connection: close</code> 表示「这是本连接上的最后一个报文」，发送后 <strong>MUST</strong> 在完成当前报文后关闭。</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connection = #connection-option</span></span>
<span class="line"><span>connection-option = token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两个职责，同一个字段：</p><ol><li><strong>列出逐跳字段名</strong>——被列出的字段只对当前连接有效，代理转发前 <strong>MUST</strong> 移除它们及 <code>Connection</code> 自身。</li><li><strong>携带 <code>close</code> 指令</strong>——<code>close</code> 是保留的连接选项，非字段名。</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connection: keep-alive, Upgrade</span></span>
<span class="line"><span>Connection: close</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>值<strong>大小写不敏感</strong>。</p><h3 id="恒为逐跳的字段" tabindex="-1">恒为逐跳的字段 <a class="header-anchor" href="#恒为逐跳的字段" aria-label="Permalink to &quot;恒为逐跳的字段&quot;">​</a></h3><p>即使未被 <code>Connection</code> 列出，以下字段也<strong>不得</strong>被代理转发：</p><p><code>Connection</code>、<code>Proxy-Connection</code>、<code>Keep-Alive</code>、<code>TE</code>、<code>Transfer-Encoding</code>、<code>Upgrade</code></p><p>代理必须逐条剥离并按需重新生成——例如可自行决定回源时是否使用 <code>chunked</code>。</p><h2 id="keep-alive" tabindex="-1">Keep-Alive <a class="header-anchor" href="#keep-alive" aria-label="Permalink to &quot;Keep-Alive&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Keep-Alive: timeout=5, max=1000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>timeout</code>：空闲多少<strong>秒</strong>后可能关闭。</li><li><code>max</code>：本连接上还能处理多少个请求（HTTP/1.1 中已少用）。</li></ul><p>关键：这是<strong>提示而非承诺</strong>，且是<strong>逐跳</strong>的——必须配 <code>Connection: Keep-Alive</code> 使用，不可跨代理传递。客户端不得依赖它精确预测关闭时机，仍须处理连接被随时关闭的情况。</p><h2 id="流水线-pipelining" tabindex="-1">流水线（pipelining） <a class="header-anchor" href="#流水线-pipelining" aria-label="Permalink to &quot;流水线（pipelining）&quot;">​</a></h2><p>客户端可在收到响应前连发多个请求。约束：</p><ul><li>服务端 <strong>MUST</strong> 按请求到达顺序回送响应（HTTP/1.1 无多路复用，响应无标识符）。</li><li>客户端<strong>不应</strong>用流水线发送<strong>非幂等</strong>请求（见<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>）——连接中断时无法判断哪些已被处理。</li><li>队头阻塞（head-of-line blocking）由此产生：一个慢响应堵住其后所有响应。这是 HTTP/2 引入流复用的直接动因。</li></ul><p>实践中主流浏览器<strong>已默认禁用</strong>流水线（实现兼容性差），改用多条并行连接。</p><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Upgrade = #protocol</span></span>
<span class="line"><span>protocol = protocol-name [&quot;/&quot; protocol-version]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>请求方声明愿意切换协议，服务端同意则返回 <strong>101 Switching Protocols</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /chat HTTP/1.1</span></span>
<span class="line"><span>Host: example.com</span></span>
<span class="line"><span>Connection: Upgrade</span></span>
<span class="line"><span>Upgrade: websocket</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>要点：</p><ul><li><strong>MUST</strong> 同时发 <code>Connection: Upgrade</code>，否则该字段必须被忽略。</li><li>服务端不同意时按普通请求正常响应（忽略 <code>Upgrade</code> 即可），不是错误。</li><li>101 之后，连接上的字节按新协议解释，不再是 HTTP/1.1。</li><li>逐跳字段，代理不得转发。</li><li>HTTP/2 中<strong>已移除</strong>（改用 <code>:protocol</code> 扩展 CONNECT）。</li></ul><h2 id="expect-与-100-continue" tabindex="-1">Expect 与 100-continue <a class="header-anchor" href="#expect-与-100-continue" aria-label="Permalink to &quot;Expect 与 100-continue&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expect = #expectation</span></span>
<span class="line"><span>expectation = token [ &quot;=&quot; ( token / quoted-string ) parameters ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>唯一标准值是 <code>100-continue</code>：客户端在发送<strong>大请求体前</strong>先发头部并等待，避免体被白发。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT /large HTTP/1.1</span></span>
<span class="line"><span>Host: example.com</span></span>
<span class="line"><span>Content-Length: 1073741824</span></span>
<span class="line"><span>Expect: 100-continue</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>各方处理规则：</p><ul><li>服务端愿意接收 → 回 <code>100 Continue</code>，客户端随即发体。</li><li>服务端拒绝 → 直接回最终状态码（如 <code>401</code>、<code>417</code>、<code>413</code>），且<strong>MUST NOT</strong> 再等待体；客户端见到最终响应后应停止发送。</li><li>服务端对<strong>未知</strong>期望值 → <strong>MUST</strong> 返回 <strong>417 (Expectation Failed)</strong>。</li><li>客户端<strong>不应</strong>无限等待：超时（常见 1–2 秒）后可直接发送体。</li><li>服务端若已收到部分体，则<strong>不得</strong>再发 <code>100 Continue</code>。</li><li>逐跳语义：代理需按下游情况自行决定是否转发或代答。</li></ul><h2 id="连接关闭与重试" tabindex="-1">连接关闭与重试 <a class="header-anchor" href="#连接关闭与重试" aria-label="Permalink to &quot;连接关闭与重试&quot;">​</a></h2><ul><li><strong>半关闭</strong>：发送方完成后可关闭写方向，仍读取对端剩余数据。服务端应在关闭前尽量读完客户端已发的数据，避免对端收到 RST 而丢失响应。</li><li><strong>重试安全性</strong>：连接在收到响应前中断时，客户端<strong>仅可自动重试幂等方法</strong>。非幂等（<code>POST</code>、<code>PATCH</code>）必须由上层决策，否则可能重复扣款、重复下单。</li><li><code>408 Request Timeout</code> 响应应带 <code>Connection: close</code>。</li></ul><p>本部分结束。下一部分从<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>开始，逐个解析方法的安全性、幂等性与可缓存性。</p>`,38)])])}const h=n(o,[["render",i]]);export{u as __pageData,h as default};
